#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
build.py -- Gop tat ca cac file masterclass thanh 1 file HTML duy nhat.

CACH DUNG:
  1. Dat file build.py nay CUNG THU MUC voi cac file masterclass
     (00-index.html, 01-...html, 02-...html, ...).
  2. Mo terminal / Command Prompt tai thu muc do va chay:
        python build.py
     (Tren Windows neu "python" khong chay, thu:  py build.py )
  3. File ket qua "masterclass-all-in-one.html" se duoc tao / cap nhat lai.

KHI NAO CAN CHAY LAI?
  - Them mot file moi (vd 16-...-masterclass.html) -> chay lai build.py
  - Sua noi dung mot file cu                       -> chay lai build.py
  - Doi ten / xoa bot file                         -> chay lai build.py

Script tu dong quet moi file ten dang  <so>-*.html  trong thu muc.
Neu co 00-index.html, ten/nhom/mo ta dep se duoc lay tu do; file moi
chua khai bao trong index se duoc tu suy ra (nhom mac dinh: "Khac").
"""
import os, re, sys, base64, json

HERE = os.path.dirname(os.path.abspath(__file__))
OUT_NAME = "masterclass-all-in-one.html"
INDEX_NAME = "00-index.html"

def read_index_meta(folder):
    p = os.path.join(folder, INDEX_NAME)
    meta = {}
    if not os.path.exists(p):
        return meta
    txt = open(p, encoding="utf-8", errors="replace").read()
    obj_re = re.compile(r"\{[^{}]*?file\s*:\s*['\"]([^'\"]+\.html)['\"][^{}]*?\}", re.S)
    def field(body, key):
        m = re.search(key + r"\s*:\s*['\"](.*?)['\"]", body, re.S)
        return m.group(1) if m else None
    for m in obj_re.finditer(txt):
        body, fn = m.group(0), m.group(1)
        meta[fn] = {
            "n":     field(body, "n") or "",
            "label": field(body, "label") or fn,
            "full":  field(body, "full") or "",
            "group": field(body, "group") or "Khac",
        }
    return meta

def derive_meta(folder, fn):
    n_m = re.match(r"(\d+)", fn)
    n = n_m.group(1) if n_m else ""
    title = fn
    try:
        head = open(os.path.join(folder, fn), encoding="utf-8", errors="replace").read(8000)
        mt = re.search(r"<title>(.*?)</title>", head, re.S | re.I)
        if mt:
            title = re.sub(r"\s+", " ", mt.group(1)).strip().replace("&amp;", "&")
    except Exception:
        pass
    label = re.split(r"\s+[—\-]\s+", title)[0][:40] or fn
    return {"n": n, "label": label, "full": title, "group": "Khac"}

def main():
    folder = HERE
    index_meta = read_index_meta(folder)

    files = []
    for fn in os.listdir(folder):
        if not re.match(r"^\d+-.*\.html$", fn):
            continue
        if fn in (INDEX_NAME, OUT_NAME):
            continue
        files.append(fn)

    if not files:
        print("Khong tim thay file masterclass nao (dang <so>-*.html) trong:", folder)
        sys.exit(1)

    docs = []
    for fn in files:
        m = index_meta.get(fn) or derive_meta(folder, fn)
        if not m.get("n"):
            nm = re.match(r"(\d+)", fn)
            m["n"] = nm.group(1) if nm else ""
        raw = open(os.path.join(folder, fn), "rb").read()
        _txt = re.sub(rb"<script[\s\S]*?</script>|<style[\s\S]*?</style>", b" ", raw, flags=re.I)
        _txt = re.sub(rb"<[^>]+>", b" ", _txt)
        _words = len(re.findall(rb"\S+", _txt))
        docs.append({
            "n": m["n"], "label": m["label"], "full": m["full"],
            "group": m["group"], "size": len(raw),
            "words": _words,
            "mins": max(5, int(round(_words / 220.0))),
            "tabs": raw.count(b'class="tab-btn'),
            "b64": base64.b64encode(raw).decode("ascii"),
        })

    docs.sort(key=lambda d: (int(re.sub(r"\D", "", d["n"]) or 0), d["n"]))

    meta = [{"n": d["n"], "label": d["label"], "full": d["full"],
             "group": d["group"], "size": d["size"],
             "words": d["words"], "mins": d["mins"], "tabs": d["tabs"]} for d in docs]
    b64map = {d["n"]: d["b64"] for d in docs}

    meta_js = json.dumps(meta, ensure_ascii=False)
    b64_js = json.dumps(b64map, ensure_ascii=False)
    for name, data in (("meta", meta_js), ("b64", b64_js)):
        if "</script" in data.lower():
            raise SystemExit("Loi an toan: du lieu chua </script (" + name + ")")

    shell = base64.b64decode(TEMPLATE_B64).decode("utf-8")
    out = shell.replace("__META__", meta_js).replace("__B64__", b64_js).replace("__COUNT__", str(len(docs)))
    open(os.path.join(folder, OUT_NAME), "w", encoding="utf-8").write(out)

    size_mb = len(out.encode("utf-8")) / 1048576.0
    print("Da gop {} file -> {} ({:.1f} MB)".format(len(docs), OUT_NAME, size_mb))
    for d in docs:
        print("  {}  {:<22} [{}]".format(d["n"], d["label"], d["group"]))

TEMPLATE_B64 = ""

if __name__ == "__main__":
    main()
